16	function httpGet(url, headers) {
17	    return new Promise((resolve, reject) => {
18	        const u    = new URL(url);
19	        const lib  = u.protocol === 'https:' ? https : http;
20	        const opts = {
21	            hostname : u.hostname,
22	            port     : u.port || (u.protocol === 'https:' ? 443 : 80),
23	            path     : u.pathname + (u.search || ''),
24	            method   : 'GET',
25	            headers  : headers || {}
26	        };
27	        const req = lib.request(opts, res => {
28	            let data = '';
29	            res.on('data', c => data += c);
30	            res.on('end', () => {
31	                try   { resolve({ status: res.statusCode, body: JSON.parse(data) }); }
32	                catch { resolve({ status: res.statusCode, body: data }); }
33	            });
34	        });
35	        req.on('error', reject);
36	        req.end();
37	    });
38	}
