29	
30	        node.listener = function ({ args, _mcpCallId, _mcpClaims }) {
31	            node.status({ fill: 'blue', shape: 'dot', text: 'called' });
32	            const msg = {
33	                payload    : args,
34	                _mcpCallId : _mcpCallId,
35	                topic      : topic
36	            };
37	            if (exposeClaims && _mcpClaims) msg.jwtClaims = _mcpClaims;
38	            node.send(msg);
39	            setTimeout(() => node.status({ fill: 'green', shape: 'dot', text: 'ready' }), 1000);
