8	// Admin-claim gate for admin-only tools (get_flow/deploy_flow). An empty adminValue means
9	// "allow any authenticated caller"; a missing/absent claim always denies.
10	function isAdmin(claims, adminClaim, adminValue) {
11	    if (!adminValue) return true;
12	    if (!claims) return false;
13	    const v = claims[adminClaim];
14	    if (Array.isArray(v)) return v.includes(adminValue);
15	    return v === adminValue;
16	}
