18	// RFC 9728: the resource identifier must equal the URL the client actually connects to
19	// (the MCP JSON-RPC endpoint), and authorization_servers must list the server(s) that can
20	// issue tokens for it.
21	function buildProtectedResourceMetadata({ resourceUrl, authServerUrl, scopes }) {
22	    return {
23	        resource                 : resourceUrl,
24	        authorization_servers    : [authServerUrl],
25	        bearer_methods_supported : ['header'],
26	        scopes_supported         : scopes
27	    };
28	}
29	
30	// RFC 8414 authorization server metadata. The MCP server proxies the real OIDC issuer's
31	// endpoints under its own `issuer` identity so MCP clients only ever need to trust one
32	// origin (this server) for discovery + DCR, while the actual authorize/token/userinfo
33	// traffic still goes straight to the real IdP.
34	function buildAuthorizationServerMetadata({ issuerBase, oidc, registrationEndpoint, scopes, hasClientSecret }) {
35	    return {
36	        issuer                                 : issuerBase,
37	        authorization_endpoint                 : oidc.authorization_endpoint,
38	        token_endpoint                         : oidc.token_endpoint,
39	        userinfo_endpoint                      : oidc.userinfo_endpoint,
40	        registration_endpoint                  : registrationEndpoint,
41	        jwks_uri                               : oidc.jwks_uri,
42	        scopes_supported                       : scopes,
43	        response_types_supported               : ['code'],
44	        grant_types_supported                  : ['authorization_code', 'refresh_token'],
45	        code_challenge_methods_supported       : ['S256'],
46	        token_endpoint_auth_methods_supported  : hasClientSecret ? ['client_secret_post', 'none'] : ['none']
47	    };
48	}
