50	// Never echo attacker-controlled redirect_uris back to the caller. Constrain any requested
51	// URIs to the configured allowlist; fall back to the full configured set when none (valid)
52	// were requested. { ok: false } signals "requested URIs, none of which are allowed" — the
53	// caller should reject with 400 rather than register anything.
54	function filterRedirectUris(requestedUris, allowedUris) {
55	    const requested = Array.isArray(requestedUris) ? requestedUris : [];
56	    const allowed   = requested.filter(u => allowedUris.includes(u));
57	    if (requested.length && !allowed.length) {
58	        return { ok: false, uris: [] };
59	    }
60	    return { ok: true, uris: allowed.length ? allowed : allowedUris };
61	}
62	
63	function buildDcrRegistration({ clientId, clientSecret, redirectUris, scopeStr }) {
64	    const registration = {
65	        client_id                  : clientId,
66	        client_id_issued_at        : Math.floor(Date.now() / 1000),
67	        redirect_uris              : redirectUris,
68	        grant_types                : ['authorization_code', 'refresh_token'],
69	        response_types             : ['code'],
70	        token_endpoint_auth_method : clientSecret ? 'client_secret_post' : 'none',
71	        scope                      : scopeStr
72	    };
73	    if (clientSecret) registration.client_secret = clientSecret;
74	    return registration;
75	}
76	
77	module.exports = {
78	    isAdmin,
79	    buildProtectedResourceMetadata,
80	    buildAuthorizationServerMetadata,
81	    filterRedirectUris,
82	    buildDcrRegistration
83	};
