            get : (p, ...h) => { routes.get[p]  = h[h.length - 1]; },
            post: (p, ...h) => { routes.post[p] = h[h.length - 1]; },
            _router: { stack: [] }
        },
        nodes: {
            createNode(node) {
                Object.setPrototypeOf(node, Object.assign(new EventEmitter(), {
                    log: () => {}, warn: () => {}, error: () => {}, status: () => {}
                }));
                EventEmitter.call(node);
            },
            registerType: () => {},
            getNode: () => null
        }
    };
}

function buildServer(serverValue, adminValue) {
    const RED = makeRED();
    let node;
    const register = require('../../../../repos/private/node-red-contrib-mcp-server/nodes/mcp-server.js');
    RED.nodes.registerType = (name, ctor) => { RED._ctor = ctor; };
    register(RED);
    node = Object.create(EventEmitter.prototype);
    EventEmitter.call(node);
    Object.assign(node, {
        log: () => {}, warn: () => {}, error: () => {}, status: () => {},
        on: EventEmitter.prototype.on.bind(node),
        credentials: { localDebugToken: DEBUG_TOKEN }
    });
    RED.nodes.createNode = (n) => {
        Object.assign(n, {
            log: () => {}, warn: () => {}, error: () => {}, status: () => {},
            credentials: { localDebugToken: DEBUG_TOKEN }
        });
        Object.setPrototypeOf(n, EventEmitter.prototype);
        EventEmitter.call(n);
    };
    const inst = {};
    RED._ctor.call(inst, {
        path: 'smoke', serverUrl: 'https://example.com', issuerUrl: 'https://idp.example.com',
        requiredClaim: 'groups', requiredValue: serverValue,
        adminToolsEnabled: true, adminRequiredValue: adminValue
    });
    return { RED, node: inst };
}

async function call(RED, node, body) {
    const handler = RED.routes.post['/mcp/smoke'];
    const req = { headers: { authorization: 'Bearer ' + DEBUG_TOKEN }, body };
    let payload, status;
    const res = {
        status(c) { status = c; return this; },
        json(o) { payload = o; return this; },
        set() { return this; },
        send() { return this; }
    };
    await handler(req, res);
    return { status, payload };
}

function tools(node, specs) {
    for (const [name, requiredValue] of specs) {
        node.registerMCPTool(name, name + ' desc', { type: 'object', properties: {} }, 5, requiredValue);
    }
}

(async () => {
    // claims from the debug token: { sub:'debug', groups:['admin'] }

    // 1. server list empty
    {
        const { RED, node } = buildServer('', 'admin');
        tools(node, [['open', ''], ['gated_admin', 'admin'], ['nope', 'nope']]);
        const list = await call(RED, node, { id: 1, method: 'tools/list' });
        const names = list.payload.result.tools.map(t => t.name);
        assert.deepStrictEqual(names, ['open', 'gated_admin', 'get_flow', 'deploy_flow'], names.join());

        const init = await call(RED, node, { id: 2, method: 'initialize' });
        assert.ok(init.payload.result.instructions.includes('open, gated_admin, get_flow, deploy_flow'),
            init.payload.result.instructions);

        const denied = await call(RED, node, { id: 3, method: 'tools/call', params: { name: 'nope' } });
        assert.strictEqual(denied.payload.result.isError, true);
        assert.ok(denied.payload.result.content[0].text.includes('"nope" tool requires a permission'));
        console.log('  denial text:', denied.payload.result.content[0].text);

        // callable tool resolves through mcp-out's resolveMCPCall
        node.on('mcp_tool_open', ({ _mcpCallId }) => node.resolveMCPCall(_mcpCallId, 'it worked'));
        const ok = await call(RED, node, { id: 4, method: 'tools/call', params: { name: 'open' } });
        assert.strictEqual(ok.payload.result.content[0].text, 'it worked');
        console.log('✔ server list empty: open+gated_admin+admin tools visible, nope hidden & denied, call resolves');
    }

    // 2. server list any-of matches
    {
        const { RED, node } = buildServer('admin, staff', 'admin');
        tools(node, [['open', ''], ['gated_admin', 'admin']]);
        const list = await call(RED, node, { id: 1, method: 'tools/list' });
        assert.deepStrictEqual(list.payload.result.tools.map(t => t.name),
            ['open', 'gated_admin', 'get_flow', 'deploy_flow']);
        console.log('✔ server list "admin, staff": any-of match on the server field');
    }

    // 3. server list not cleared -> AND blocks everything, tool's own list does not help
    {
        const { RED, node } = buildServer('staff', 'admin');
        tools(node, [['open', ''], ['gated_admin', 'admin']]);
        const list = await call(RED, node, { id: 1, method: 'tools/list' });
        assert.deepStrictEqual(list.payload.result.tools, []);
        const denied = await call(RED, node, { id: 2, method: 'tools/call', params: { name: 'gated_admin' } });
        assert.strictEqual(denied.payload.result.isError, true);
        assert.ok(denied.payload.result.content[0].text.includes('use this server'));
        const gf = await call(RED, node, { id: 3, method: 'tools/call', params: { name: 'get_flow' } });
        assert.strictEqual(gf.payload.result.isError, true);
        const init = await call(RED, node, { id: 4, method: 'initialize' });
        assert.ok(!init.payload.result.instructions.includes('Available tools'), init.payload.result.instructions);
        console.log('✔ server list "staff": everything denied — AND holds, tool list cannot bypass it');
    }

    // 4. admin list not matched -> admin tools gone, ordinary tools fine
    {
        const { RED, node } = buildServer('', 'superuser');
        tools(node, [['open', '']]);
        const list = await call(RED, node, { id: 1, method: 'tools/list' });
        assert.deepStrictEqual(list.payload.result.tools.map(t => t.name), ['open']);
        const gf = await call(RED, node, { id: 2, method: 'tools/call', params: { name: 'get_flow' } });
        assert.strictEqual(gf.payload.result.isError, true);
        assert.ok(gf.payload.result.content[0].text.includes('admin privileges'));
        console.log('✔ admin list "superuser": admin tools hidden and denied, ordinary tool unaffected');
    }

    // 5. a stale mcp-in registering with 4 args stays unconstrained
    {
        const { RED, node } = buildServer('', 'admin');
        node.registerMCPTool('legacy', 'legacy desc', { type: 'object', properties: {} }, 5);
        const list = await call(RED, node, { id: 1, method: 'tools/list' });
        assert.ok(list.payload.result.tools.some(t => t.name === 'legacy'));
        console.log('✔ 4-arg registerMCPTool (older mcp-in) stays unconstrained');
    }

    console.log('\nall smoke checks passed');
})().catch(e => { console.error('FAILED:', e.message); process.exit(1); });

