2	// MCP authentication surface: OIDC discovery, JWKS, token validation and the Bearer
3	// middleware used by the mcp-server config node. All external dependencies (HTTP,
4	// logging, and the jose primitives) are injectable, so tests need neither a live IdP
5	// nor a running Node-RED.
6	
7	const crypto = require('crypto');
8	const jose   = require('jose');
9	
10	const TOKEN_CACHE_MAX = 1000;
11	
12	// Constant-time secret comparison that does not leak length. Both inputs are hashed to a
13	// fixed-width digest before timingSafeEqual, so mismatched lengths compare safely.
14	function secretEqual(a, b) {
15	    const ha = crypto.createHash('sha256').update(String(a)).digest();
16	    const hb = crypto.createHash('sha256').update(String(b)).digest();
17	    return crypto.timingSafeEqual(ha, hb);
18	}
19	
20	function createMcpAuth(opts) {
21	    const {
22	        issuerUrl          = '',
23	        tokenTTL           = 300000,
24	        tokenAudience      = '',
25	        localDebugToken    = '',
26	        mcpServerUrl       = '',
27	        discoveryRetryMs   = 30000,
28	        httpGet,
29	        log                = () => {},
30	        warn               = () => {},
31	        // Injectable for tests; default to the real jose primitives.
32	        jwtVerify          = jose.jwtVerify,
33	        createRemoteJWKSet = jose.createRemoteJWKSet
34	    } = opts || {};
35	
36	    if (typeof httpGet !== 'function') {
37	        throw new Error('createMcpAuth requires an httpGet function');
38	    }
39	
40	    let tokenCache = {};
41	    let oidcConfig = null, oidcConfigPromise = null, oidcRetryAt = 0;
42	    let jwks = null, jwksUri = null;
43	
44	    // OIDC discovery with PocketID-style fallback paths. Discover the IdP's real endpoints
45	    // from /.well-known/openid-configuration so any spec-compliant OIDC provider works; fall
46	    // back to the PocketID path layout when discovery is unavailable.
47	    function fallbackEndpoints() {
48	        return {
49	            issuer                 : issuerUrl,
50	            authorization_endpoint : issuerUrl + '/authorize',
51	            token_endpoint         : issuerUrl + '/api/oidc/token',
52	            userinfo_endpoint      : issuerUrl + '/api/oidc/userinfo',
53	            jwks_uri               : issuerUrl + '/.well-known/jwks.json'
54	        };
55	    }
56	
57	    function getOidcConfig() {
58	        if (oidcConfig) return Promise.resolve(oidcConfig);
59	        // Only successful discovery is cached. After a failure the fallback is served
60	        // without re-probing until the retry window has passed, so a transient IdP
61	        // outage (e.g. during deploy) neither pins the fallback forever nor turns every
62	        // request into a discovery attempt against a dead IdP.
63	        if (!oidcConfigPromise && Date.now() < oidcRetryAt) {
64	            return Promise.resolve(fallbackEndpoints());
65	        }
66	        if (!oidcConfigPromise) {
67	            oidcConfigPromise = (async () => {
68	                const fb = fallbackEndpoints();
69	                if (!issuerUrl) { oidcConfig = fb; return fb; }
70	                try {
71	                    const r = await httpGet(issuerUrl + '/.well-known/openid-configuration', {});
72	                    if (r.status === 200 && r.body && typeof r.body === 'object' && r.body.jwks_uri) {
73	                        oidcConfig = Object.assign(fb, r.body);   // discovered values win, per-field fallback
74	                        log('MCP OIDC discovery ok: issuer=' + oidcConfig.issuer);
75	                        return oidcConfig;
76	                    }
77	                    warn('MCP OIDC discovery returned ' + r.status + ' — using fallback endpoint paths');
78	                } catch (e) {
79	                    warn('MCP OIDC discovery failed: ' + e.message + ' — using fallback endpoint paths');
80	                }
81	                oidcConfigPromise = null;
82	                oidcRetryAt = Date.now() + discoveryRetryMs;
83	                return fb;
84	            })();
85	        }
86	        return oidcConfigPromise;
87	    }
88	
89	    // Lazy JWKS — built from the discovered jwks_uri on first real token validation, and
90	    // rebuilt if a later re-discovery changes the jwks_uri (fallback → discovered).
91	    async function getJwks() {
92	        const oidc = await getOidcConfig();
93	        if (!jwks || jwksUri !== oidc.jwks_uri) {
94	            jwksUri = oidc.jwks_uri;
95	            jwks = createRemoteJWKSet(new URL(jwksUri));
96	        }
97	        return jwks;
98	    }
99	
100	    // Insert into the token cache with a hard size cap: drop expired entries first, then evict
101	    // the soonest-to-expire until back under the cap. Prevents unbounded growth (and OOM) from
102	    // a flood of unique tokens on an internet-exposed endpoint.
103	    function cacheToken(key, entry) {
104	        tokenCache[key] = entry;
105	        const keys = Object.keys(tokenCache);
106	        if (keys.length <= TOKEN_CACHE_MAX) return;
107	        const now = Date.now();
108	        for (const k of keys) { if (tokenCache[k].exp < now) delete tokenCache[k]; }
109	        let remaining = Object.keys(tokenCache);
110	        if (remaining.length > TOKEN_CACHE_MAX) {
111	            remaining.sort((x, y) => tokenCache[x].exp - tokenCache[y].exp);
112	            for (let i = 0; i < remaining.length - TOKEN_CACHE_MAX; i++) delete tokenCache[remaining[i]];
113	        }
114	    }
115	
116	    async function validateToken(token) {
117	        // Local debug token bypass — skips the IdP entirely. Constant-time compare so the token
118	        // can't be recovered by timing the response.
119	        if (localDebugToken && secretEqual(token, localDebugToken)) {
120	            return { sub: 'debug', name: 'Local debug user', groups: ['admin'] };
121	        }
122	
123	        const cacheKey = 'auth_' + crypto.createHash('sha256').update(token).digest('hex').slice(0, 20);
124	        if (Object.prototype.hasOwnProperty.call(tokenCache, cacheKey)
125	            && tokenCache[cacheKey].exp >= Date.now()) {
126	            return tokenCache[cacheKey].claims;
127	        }
128	        try {
129	            const oidc = await getOidcConfig();
130	            // Always pin the issuer to the discovered IdP; enforce audience only when configured.
131	            // Without these, any signature-valid token from a provider that shares the JWKS would
132	            // be accepted.
133	            const verifyOpts = {};
134	            if (oidc.issuer) verifyOpts.issuer = oidc.issuer;
135	            if (tokenAudience) verifyOpts.audience = tokenAudience;
136	            const { payload } = await jwtVerify(token, await getJwks(), verifyOpts);
137	            // Enrich with userinfo — access tokens are minimal by OIDC convention, rich claims
138	            // (email, name, groups) live in the userinfo response. JWT payload wins on collisions
139	            // so verified fields stay authoritative.
140	            let claims = payload;
141	            try {
142	                const r = await httpGet(oidc.userinfo_endpoint, { 'Authorization': 'Bearer ' + token });
143	                if (r.status === 200 && r.body && typeof r.body === 'object') {
144	                    claims = Object.assign({}, r.body, payload);
145	                } else {
146	                    warn('MCP userinfo returned ' + r.status + ' — using JWT claims only');
147	                }
148	            } catch (e) {
149	                warn('MCP userinfo fetch failed: ' + e.message + ' — using JWT claims only');
150	            }
151	            const tokenExpMs = (typeof payload.exp === 'number') ? payload.exp * 1000 : Infinity;
152	            const cacheExp = Math.min(Date.now() + tokenTTL, tokenExpMs);
153	            cacheToken(cacheKey, { claims, exp: cacheExp });
154	            return claims;
155	        } catch (e) {
156	            warn('MCP token verify failed: ' + e.message);
157	            return null;
158	        }
159	    }
160	
161	    async function requireBearer(req, res) {
162	        const authHeader = req.headers['authorization'] || '';
163	        if (!authHeader.startsWith('Bearer ')) {
164	            res.set('WWW-Authenticate',
165	                `Bearer resource_metadata="${mcpServerUrl}/.well-known/oauth-protected-resource"`);
166	            res.status(401).json({ error: 'unauthorized' });
167	            return null;
168	        }
169	        const token  = authHeader.slice(7);
170	        const claims = await validateToken(token);
171	        if (!claims) {
172	            res.set('WWW-Authenticate',
173	                `Bearer error="invalid_token", resource_metadata="${mcpServerUrl}/.well-known/oauth-protected-resource"`);
174	            res.status(401).json({ error: 'invalid_token' });
175	            return null;
176	        }
177	        return claims;
178	    }
179	
180	    return {
181	        validateToken,
182	        requireBearer,
183	        getOidcConfig,
184	        clearCache: () => { tokenCache = {}; },
185	        cacheSize:  () => Object.keys(tokenCache).length
186	    };
187	}
188	
189	module.exports = { createMcpAuth, secretEqual };
