1	'use strict';
2	// HTTP hardening middleware for internet-exposed MCP routes: per-IP rate limiting
3	// (sliding 60s window) and a Content-Length cap. Express-style (req, res, next)
4	// middlewares, shared by the mcp-server config node's MCP and admin routes, and
5	// unit-testable without Node-RED. Node-RED's own body parser still applies; these
6	// are cheap early guards.
7	
8	// createHttpGuards({ warn }) → { rateLimit(bucket, perMinute), maxBody(bytes) }.
9	// One hit store per factory instance, shared across that instance's buckets.
10	function createHttpGuards(opts) {
11	    const warn  = (opts && opts.warn) || (() => {});
12	    const store = {};
13	    let proxyWarned = false;
14	
15	    function rateLimit(bucket, perMinute) {
16	        return (req, res, next) => {
17	            const ip = req.ip || (req.connection && req.connection.remoteAddress) || 'unknown';
18	            // Behind a reverse proxy Express only honours X-Forwarded-For when its
19	            // 'trust proxy' setting is on — otherwise every client shares the proxy's
20	            // IP and one abuser rate-limits everybody. Warn once when that's detected.
21	            if (!proxyWarned && req.headers && req.headers['x-forwarded-for']
22	                && req.app && typeof req.app.get === 'function' && !req.app.get('trust proxy')) {
23	                proxyWarned = true;
24	                warn('Rate limiting sees the reverse proxy\'s IP for every client (X-Forwarded-For is ignored). ' +
25	                     'Set "trust proxy" in Node-RED\'s httpServerOptions so limits apply per real client.');
26	            }
27	            const key = bucket + '|' + ip;
28	            const now = Date.now();
29	            const win = now - 60000;
30	            const hits = (store[key] || []).filter(t => t > win);
31	            if (hits.length >= perMinute) {
32	                res.set('Retry-After', '60');
33	                return res.status(429).json({ error: 'rate_limited' });
34	            }
35	            hits.push(now);
36	            store[key] = hits;
37	            if (Object.keys(store).length > 5000) {            // bound memory
38	                for (const k of Object.keys(store)) {
39	                    if (!store[k].some(t => t > win)) delete store[k];
40	                }
41	            }
42	            next();
43	        };
44	    }
45	
46	    function maxBody(bytes) {
47	        return (req, res, next) => {
48	            if (Number(req.headers['content-length'] || 0) > bytes) {
49	                return res.status(413).json({ error: 'payload_too_large' });
50	            }
51	            next();
52	        };
53	    }
54	
55	    return { rateLimit, maxBody };
56	}
57	
58	// hostFilter(expectedHost) → middleware that only lets requests whose Host header matches
59	// expectedHost run this route's handler. On a mismatch it calls next('route'), skipping the
60	// rest of *this* route so another route on the shared router (same path, different hostname —
61	// e.g. a second mcp-server node) gets its turn. This is what makes hostname-based splitting
62	// work: several nodes can register the identical path and be told apart by Host.
63	//
64	// expectedHost falsy → the feature is off: every request passes through and matching stays
65	// path-only, so single-server setups (and anyone behind a proxy that rewrites Host) are
66	// untouched. Compared case-insensitively; the port is part of the Host header so keep it in
67	// expectedHost if the public URL carries a non-default port. Put this first in the chain so
68	// mismatches skip before consuming the rate-limit budget.
69	function hostFilter(expectedHost) {
70	    const want = expectedHost ? String(expectedHost).toLowerCase() : '';
71	    return (req, res, next) => {
72	        if (!want) return next();
73	        const got = String((req.headers && req.headers.host) || '').toLowerCase();
74	        if (got !== want) return next('route');
75	        return next();
76	    };
77	}
78	
79	module.exports = { createHttpGuards, hostFilter };
