7	const http = require('http');
8	
9	function defaultHttpRequest(method, hostname, port, path, headers, body) {
10	    return new Promise((resolve, reject) => {
11	        const data = body ? JSON.stringify(body) : null;
12	        const hdrs = Object.assign({ 'Content-Type': 'application/json', 'Node-RED-API-Version': 'v2' }, headers);
13	        if (data) hdrs['Content-Length'] = Buffer.byteLength(data);
14	        const req = http.request({ method, hostname, port, path, headers: hdrs }, res => {
15	            let raw = '';
16	            res.on('data', c => raw += c);
17	            res.on('end', () => {
18	                try   { resolve({ status: res.statusCode, body: JSON.parse(raw) }); }
19	                catch { resolve({ status: res.statusCode, body: raw }); }
20	            });
21	        });
22	        req.on('error', reject);
23	        if (data) req.write(data);
