function makeRED() {
    const routes = { get: {}, post: {} };
    const router = { stack: [] };
    // Mimic just enough of Express: remember the last handler for direct calling, and build
    // route layers the way removeRoute expects to filter them.
    const reg = method => (p, ...h) => {
        routes[method][p] = h[h.length - 1];
        router.stack.push({ route: { path: p, methods: { [method]: true }, stack: h.map(fn => ({ handle: fn })) } });
    };
    return {
        routes,
        httpNode: { get: reg('get'), post: reg('post'), _router: router },
        nodes: {
            createNode(node) {
                Object.setPrototypeOf(node, Object.assign(new EventEmitter(), {
                    log: () => {}, warn: () => {}, error: () => {}, status: () => {}
                }));
                EventEmitter.call(node);
            },
            registerType: () => {},
            getNode: () => null
        }
    };
}

