const registerNode = require(process.env.PKG + '/nodes/mcp-server.js');

function buildServer(serverValue, adminValue, opts = {}) {
    const RED = opts.RED || makeRED();
    let ctor;
    RED.nodes.registerType = (name, c) => { ctor = c; };
    RED.nodes.createNode = (n, cfg) => {
        Object.setPrototypeOf(n, EventEmitter.prototype);
        EventEmitter.call(n);
        Object.assign(n, {
            id: cfg.id,
            log: () => {}, warn: m => (n.warnings = (n.warnings || [])).push(m),
            error: () => {}, status: () => {},
            credentials: { localDebugToken: DEBUG_TOKEN }
        });
    };
    registerNode(RED);
    const node = {};
    ctor.call(node, Object.assign({
        id: opts.id || 'srv-1',
        path: 'smoke', serverUrl: 'https://example.com', issuerUrl: 'https://idp.example.com',
        requiredClaim: 'groups', requiredValue: serverValue,
        adminToolsEnabled: true, adminRequiredValue: adminValue
    }, opts.config));
    return { RED, node };
}

// 6. ping answered, unknown method still -32601
{
    const { RED, node } = buildServer('', 'admin');
    const ping = await call(RED, node, { id: 9, method: 'ping' });
    assert.deepStrictEqual(ping.payload, { jsonrpc: '2.0', id: 9, result: {} });
    const nope = await call(RED, node, { id: 10, method: 'bogus' });
    assert.strictEqual(nope.payload.error.code, -32601);
    console.log('✔ ping → {}, unknown method → -32601');
}

// 7. A2: two servers sharing a path — closing one leaves the sibling's routes intact
{
    const RED = makeRED();
    const a = buildServer('', 'admin', { RED, id: 'srv-a',
        config: { filterHost: true, serverUrl: 'https://a.example.com' } }).node;
    const b = buildServer('', 'admin', { RED, id: 'srv-b',
        config: { filterHost: true, serverUrl: 'https://b.example.com' } }).node;
    tools(b, [['b_tool', '']]);
    const layersFor = () => RED.httpNode._router.stack.filter(l => l.route.path === '/mcp/smoke');
    assert.strictEqual(layersFor().length, 2);
    a.emit('close');
    const left = layersFor();
    assert.strictEqual(left.length, 1);
    assert.ok(left[0].route.stack.some(l => l.handle._mcpOwner === 'srv-b'), 'survivor is srv-b');
    // ...and the surviving server still answers.
    const list = await call(RED, b, { id: 1, method: 'tools/list' });
    assert.deepStrictEqual(list.payload.result.tools.map(t => t.name),
        ['b_tool', 'get_flow', 'deploy_flow']);
    console.log('✔ shared path: closing server A leaves server B routed and answering');
}

// 8. A3: duplicate toolName warns; removing one owner does not tear down the other
{
    const { RED, node } = buildServer('', 'admin');
    node.registerMCPTool('dup', 'first', {}, 5, '', 'in-1');
    node.registerMCPTool('dup', 'second', {}, 5, '', 'in-2');
    assert.strictEqual((node.warnings || []).filter(w => w.includes('"dup"')).length, 1);
    node.unregisterMCPTool('dup', 'in-1');          // loser closes — survivor must stay
    assert.ok(node.mcpRegisteredTools['dup'], 'in-2 registration survives');
    node.unregisterMCPTool('dup', 'in-2');
    assert.strictEqual(node.mcpRegisteredTools['dup'], undefined);
    console.log('✔ duplicate toolName: warned once, ownership-checked unregister');
}

